<script setup>defineProps({ selectedText:String, result:Object })</script>
<template><section class="analysis"><h3>作品与背景</h3><template v-if="result"><p>{{ result.summary }}</p><template v-if="result.literary_context"><h4>结构与表达</h4><p>{{ result.literary_context }}</p></template><p v-if="result.historical_context">{{ result.historical_context }}</p><div class="keyword-list"><span v-for="word in result.keywords" :key="word" class="pill">{{ word }}</span></div><section v-if="result.corpus?.length" class="corpus-results"><h4>关联语料</h4><p class="muted">主题关联用于对照阅读，不表示选文直接引用了这些作品。</p><article v-for="item in result.corpus" :key="item.id || item.title" class="corpus-card"><a :href="item.source" target="_blank" rel="noopener noreferrer">{{ item.title }} ↗</a><small>{{ item.author }} · {{ item.dynasty }}</small><p>{{ item.text.slice(0,160) }}{{ item.text.length>160?'…':'' }}</p><small>{{ item.relation }}</small></article></section><p class="result-source">{{ result.source_label || 'AI 生成内容，请结合原文核对' }}</p></template><p v-else class="empty">选取一篇文章，开始探索。</p></section></template>
